/**
 * n8n Code — entrada do subfluxo CADASTRO SOFIA v4
 * Aceita body do Webhook Sofia OU inputs do Execute Workflow.
 * Saída: mesmo shape do antigo "Buscando cliente" (Postgres), sem DB.
 */
const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

function digits(v) {
  return String(v ?? '').replace(/\D/g, '');
}

function telBr(v) {
  let n = digits(v);
  if (n.length === 13 && n.startsWith('55')) n = n.slice(2);
  return n;
}

const ixc = String(body.ixc_cliente_id || body.ixc_id_cliente || '').trim();

return [
  {
    json: {
      id_cliente: String(body.id_cliente || ''),
      conversation_id: String(body.conversation_id || ''),
      contact_id: String(body.contact_id || ''),
      nome: String(body.nome || ''),
      cpf_cnpj: digits(body.cpf || body.cpf_cnpj),
      email: String(body.email || ''),
      telefone: telBr(body.telefone),
      whatsapp: telBr(body.telefone),
      cep: String(body.cep || ''),
      rua: String(body.rua || ''),
      numero_endereco: String(body.numero || body.numero_endereco || ''),
      bairro: String(body.bairro || ''),
      cidade: String(body.cidade || ''),
      complemento: String(body.complemento || 'Sem complemento'),
      data_nascimento: String(body.data_nascimento || ''),
      plano_id: String(body.plano_confirmado_id || body.plano_id || body.id_vd_contrato || ''),
      plano_confirmado: String(body.plano_confirmado || ''),
      rg_cliente: digits(body.rg || body.rg_cliente),
      localizacao: String(body.localizacao_fixa || body.localizacao || ''),
      caixa_fibra: String(body.caixa_fibra || ''),
      data_vencimento: String(body.data_vencimento_pref || body.data_vencimento || '5'),
      data_hora_agendamento: String(body.data_hora_agendamento || ''),
      ixc_id_cliente: ixc,
      cadastrado: ixc ? 'sim' : 'nao',
    },
  },
];

/**
 * n8n Code — ID IXC unificado (cliente novo ou já existente).
 * Conecte ANTES de Coleta_id_cidade_cadastra nos dois ramos do If cadastrado.
 */
const norm = $('Normalizar Sofia').first().json;
let ixcId = String(norm.ixc_id_cliente || '').trim();

const criados = $('cadastro_cliente').all();
if (criados.length > 0 && criados[0].json?.id) {
  ixcId = String(criados[0].json.id).trim();
}

if (!ixcId) {
  throw new Error('ixc_id_cliente vazio — cadastro_cliente falhou ou ixc_cliente_id não veio no payload');
}

return [{ json: { ixc_id_cliente: ixcId, cadastrado: 'sim' } }];

const cidade = String($json.cidade || "");
const cpf = String($json.cpf || "");
const mapa = { santarem:"stm", alenquer:"alq", altamira:"atm", "brasil novo":"bn", medicilandia:"med", uruara:"uru", ruropolis:"rp", itaituba:"itb", "mojui dos campos":"mjc" };
const norm = (t) => String(t).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim();
const sigla = mapa[norm(cidade)] || "??";
return [{ json: { ...$json, pppoe: cpf.replace(/\D/g,"") + "_" + sigla } }];

/**
 * n8n Code — resposta final para a Sofia (Respond to Webhook / retorno subfluxo)
 * Conecte após OS OK + labels Chatwoot (opcional).
 */
const cliente = $('Normalizar Sofia').first().json;
const unificado = $('Cliente IXC ID').first()?.json || {};
const ixcId =
  String(unificado.ixc_id_cliente || '').trim() ||
  String(cliente.ixc_id_cliente || '').trim() ||
  String($('cadastro_cliente').first()?.json?.id || '').trim();

const contrato = $('retorno_contrato').first()?.json || {};
const osNode = $('OS').first()?.json || {};
const loginNode = $('cadastro_login').first()?.json || $('cadastro_login1').first()?.json || {};

const idContrato = String(contrato.id_contrato || '').trim();
const osId = String(osNode.id || osNode.os_id || '').trim();
const idLogin = String(loginNode.id || '').trim();

const ok = Boolean(ixcId && idContrato && osId);

return [
  {
    json: {
      resultado: ok ? 'ok' : 'erro',
      ixc_cliente_id: ixcId,
      id_contrato_ixc: idContrato,
      os_id: osId,
      id_login: idLogin,
      motivo: ok
        ? 'Cadastro concluído (cliente + contrato + login + OS)'
        : `Incompleto: ixc=${ixcId || '-'} contrato=${idContrato || '-'} os=${osId || '-'}`,
      erro: !ok,
    },
  },
];
